     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="root"></div>

     <script>
       const faqs = [
         {
           question: "Why do cats purr?",
           answer:
             "Cats often purr when they feel relaxed, but they may also purr to self-soothe, ask for attention, or comfort themselves when stressed."
         },
         {
           question: "How much sleep do cats need?",
           answer:
             "Most adult cats sleep 12 to 16 hours a day. Kittens and senior cats may sleep even longer because growth and recovery take extra energy."
         },
         {
           question: "Should cats drink milk?",
           answer:
             "Many cats are lactose intolerant, so milk can upset their stomachs. Fresh water is the safest daily drink, with treats chosen for cats instead."
         },
         {
           question: "Why do cats knead blankets or people?",
           answer:
             "Kneading is a comforting behavior that starts in kittenhood. Adult cats often knead when they feel secure, cozy, or ready to settle down."
         },
         {
           question: "How can I keep an indoor cat entertained?",
           answer:
             "Rotate toys, provide scratching posts, offer window views, use puzzle feeders, and schedule short interactive play sessions that let your cat chase and pounce."
         }
       ];

       const escapeHtml = (value) =>
         value.replace(/[&<>"']/g, (character) => {
           const entities = {
             "&": "&amp;",
             "<": "&lt;",
             ">": "&gt;",
             '"': "&quot;",
             "'": "&#39;"
           };
           return entities[character];
         });

       function FAQItem({ question, answer }, index) {
         const panelId = `faq-panel-${index + 1}`;

         return `
           <div class="example">
             <h3 class="question">
               <button
                 class="trigger"
                 type="button"
                 aria-expanded="true"
                 aria-controls="${panelId}"
                 data-disclosure-button
               >
                 <span>${escapeHtml(question)}</span>
                 <span class="icon" aria-hidden="true">+</span>
               </button>
             </h3>
             <div class="details" id="${panelId}">
               <p>${escapeHtml(answer)}</p>
             </div>
           </div>
         `;
       }

       function App() {
         return `
           <header class="page">
             <section class="hero" aria-labelledby="page-title">
               <div class="hero-copy">
                 <p class="eyebrow">Cat care basics</p>
                 <h1 id="page-title">Cat FAQ</h1>
               </div>
               <p class="intro">
                 Quick, practical answers for curious cat people. Expand any question
                 to learn more about everyday feline behavior and care.
               </p>
             </section>
           </header>
           <main class="page" id="main-content">
             <section class="faq-shell" aria-labelledby="faq-heading">
               <h2 id="faq-heading" class="visually-hidden">Frequently asked questions about cats</h2>
               ${faqs.map(FAQItem).join("")}
             </section>
           </main>
         `;
       }

       function initializeDisclosures(root) {
         root.querySelectorAll("[data-disclosure-button]").forEach((button) => {
           const panelId = button.getAttribute("aria-controls");
           const panel = document.getElementById(panelId);

           if (!panel) {
             throw new Error(`Missing disclosure panel: ${panelId}`);
           }

           button.setAttribute("aria-expanded", "false");
           panel.hidden = true;

           button.addEventListener("click", () => {
             const isOpen = button.getAttribute("aria-expanded") === "true";
             button.setAttribute("aria-expanded", String(!isOpen));
             panel.hidden = isOpen;
           });

           button.addEventListener("keydown", (event) => {
             if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
               button.setAttribute("aria-expanded", "false");
               panel.hidden = true;
             }
           });
         });
       }

       const root = document.getElementById("root");
       root.innerHTML = App();
       initializeDisclosures(root);
     </script>
   </body>
 </html>

