      .intro {
        max-width: 62ch;
        margin: 0;
        color: var(--muted);
        font-size: clamp(1.05rem, 2vw, 1.25rem);
      }

      .visually-hidden {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      .faq-shell {
        display: grid;
        gap: 1rem;
        padding: clamp(0.75rem, 2vw, 1rem);
        background: rgba(255, 255, 255, 0.62);
        border: 1px solid rgba(217, 225, 238, 0.78);
        border-radius: var(--radius-lg);
        backdrop-filter: blur(18px);
      }

      .example {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: var(--radius-md);
        box-shadow: 0 12px 35px rgba(31, 48, 84, 0.08);
        transition:
          border-color 180ms ease,
          box-shadow 180ms ease,
          transform 180ms ease;
