    <script>
      function DisclosureItem(button) {
        return {
          initialize() {
          const panelId = button.getAttribute("aria-controls");
          const panel = document.getElementById(panelId);

          if (!panel) {
            throw new Error(`Missing disclosure panel: ${panelId}`);
          }

          button.setAttribute("aria-expanded", "false");
          panel.hidden = true;

          button.addEventListener("click", () => {
            const isOpen = button.getAttribute("aria-expanded") === "true";
            button.setAttribute("aria-expanded", String(!isOpen));
            panel.hidden = isOpen;
          });

          button.addEventListener("keydown", (event) => {
            if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
              button.setAttribute("aria-expanded", "false");
              panel.hidden = true;
            }
          });
          }
        };
      }

      function initializeDisclosures(root) {
        root.querySelectorAll("[data-disclosure-button]").forEach((button) => {
          DisclosureItem(button).initialize();
        });
      }

      initializeDisclosures(document);
    </script>
