        background: rgba(255, 255, 255, 0.62);
        border: 1px solid rgba(217, 225, 238, 0.78);
        border-radius: var(--radius-lg);
        backdrop-filter: blur(18px);
      }

      .example {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: var(--radius-md);
        box-shadow: 0 12px 35px rgba(31, 48, 84, 0.08);
        transition:
          border-color 180ms ease,
          box-shadow 180ms ease,
          transform 180ms ease;
      }

      .example:has([aria-expanded="true"]) {
        border-color: rgba(49, 87, 213, 0.42);
        box-shadow: 0 18px 45px rgba(31, 48, 84, 0.12);
        transform: translateY(-1px);
      }

      .question {
        margin: 0;
      }

      .trigger {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        gap: 1rem;
        align-items: center;
        width: 100%;
        min-height: 4.25rem;
        padding: 1.25rem clamp(1rem, 3vw, 1.5rem);
        color: inherit;
        font: inherit;
        font-size: clamp(1.05rem, 2vw, 1.2rem);
        font-weight: 750;
        text-align: left;
        background: transparent;
        border: 0;
        border-radius: var(--radius-md);
        cursor: pointer;
      }

      .trigger:hover {
        color: var(--accent-strong);
      }

      .trigger:focus-visible {
        outline: 4px solid var(--accent);
        outline-offset: 4px;
      }

      .icon {
        display: inline-grid;
        place-items: center;
        width: 2rem;
        height: 2rem;
        color: var(--accent-strong);
        background: var(--surface-soft);
        border: 1px solid rgba(49, 87, 213, 0.18);
        border-radius: 50%;
        transition: transform 180ms ease;
      }

      .trigger[aria-expanded="true"] .icon {
        transform: rotate(45deg);
      }

      .details {
        padding: 0 clamp(1rem, 3vw, 1.5rem) 1.4rem;
        color: var(--muted);
      }

      .details p {
        max-width: 72ch;
        margin: 0;
        padding-top: 0.15rem;
      }

      .details[hidden] {
        display: none;
      }

      @media (min-width: 820px) {
        .hero {
          grid-template-columns: minmax(18rem, 0.8fr) minmax(24rem, 1fr);
          align-items: end;
        }

        .hero-copy {
          display: grid;
          gap: 1rem;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
