         clip: rect(0, 0, 0, 0);
         white-space: nowrap;
         border: 0;
       }

       .faq-shell {
         display: grid;
         gap: 1rem;
         padding: clamp(0.75rem, 2vw, 1rem);
         background: rgba(255, 255, 255, 0.62);
         border: 1px solid rgba(217, 225, 238, 0.78);
         border-radius: var(--radius-lg);
         backdrop-filter: blur(18px);
       }

       .example {
         background: var(--surface);
         border: 1px solid var(--border);
         border-radius: var(--radius-md);
         box-shadow: 0 12px 35px rgba(31, 48, 84, 0.08);
         transition:
           border-color 180ms ease,
           box-shadow 180ms ease,
           transform 180ms ease;
       }

       .example:has([aria-expanded="true"]) {
         border-color: rgba(49, 87, 213, 0.42);
         box-shadow: 0 18px 45px rgba(31, 48, 84, 0.12);
         transform: translateY(-1px);
       }

       .question {
         margin: 0;
       }

       .trigger {
         display: grid;
         grid-template-columns: minmax(0, 1fr) auto;
         gap: 1rem;
         align-items: center;
         width: 100%;
         min-height: 4.25rem;
         padding: 1.25rem clamp(1rem, 3vw, 1.5rem);
         color: inherit;
         font: inherit;
         font-size: clamp(1.05rem, 2vw, 1.2rem);
         font-weight: 750;
         text-align: left;
         background: transparent;
         border: 0;
         border-radius: var(--radius-md);
         cursor: pointer;
       }

       .trigger:hover {
         color: var(--accent-strong);
       }

       .trigger:focus-visible {
         outline: 4px solid var(--accent);
         outline-offset: 4px;
       }

       .icon {
         display: inline-grid;
         place-items: center;
         width: 2rem;
         height: 2rem;
         color: var(--accent-strong);
         background: var(--surface-soft);
         border: 1px solid rgba(49, 87, 213, 0.18);
         border-radius: 50%;
         transition: transform 180ms ease;
       }

       .trigger[aria-expanded="true"] .icon {
         transform: rotate(45deg);
       }

       .details {
         padding: 0 clamp(1rem, 3vw, 1.5rem) 1.4rem;
         color: var(--muted);
       }

       .details p {
         max-width: 72ch;
         margin: 0;
         padding-top: 0.15rem;
       }

       .details[hidden] {
         display: none;
       }

       @media (min-width: 820px) {
         .hero {
           grid-template-columns: minmax(18rem, 0.8fr) minmax(24rem, 1fr);
           align-items: end;
         }

         .hero-copy {
           display: grid;
           gap: 1rem;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           scroll-behavior: auto !important;
           transition-duration: 0.01ms !important;
           animation-duration: 0.01ms !important;
           animation-iteration-count: 1 !important;
         }
       }

       @media (forced-colors: active) {
         .hero,
         .faq-shell,
         .example,
         .icon,
         .eyebrow {
           border: 1px solid CanvasText;
           box-shadow: none;
         }

         .trigger:focus-visible,
         .skip-link:focus {
           outline: 3px solid Highlight;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main class="page" id="main-content">
       <section class="hero" aria-labelledby="page-title">
         <div class="hero-copy">
           <p class="eyebrow">Cat care basics</p>
           <h1 id="page-title">Cat FAQ</h1>
         </div>
         <p class="intro">
           Quick, practical answers for curious cat people. Expand any question
           to learn more about everyday feline behavior and care.
         </p>
       </section>

       <section class="faq-shell" aria-labelledby="faq-heading">
         <h2 id="faq-heading" class="visually-hidden">Frequently asked questions about cats</h2>

         <div class="example" data-component="FAQItem">
           <h3 class="question">
             <button
               class="trigger"
               type="button"
               aria-expanded="true"
               aria-controls="faq-panel-1"
               data-disclosure-button
             >
               <span>Why do cats purr?</span>
               <span class="icon" aria-hidden="true">+</span>
             </button>
           </h3>
           <div class="details" id="faq-panel-1">
             <p>Cats often purr when they feel relaxed, but they may also purr to self-soothe, ask for attention, or comfort themselves when stressed.</p>
           </div>
         </div>

         <div class="example" data-component="FAQItem">
           <h3 class="question">
             <button
               class="trigger"
               type="button"
               aria-expanded="true"
               aria-controls="faq-panel-2"
               data-disclosure-button
             >
               <span>How much sleep do cats need?</span>
               <span class="icon" aria-hidden="true">+</span>
             </button>
           </h3>
           <div class="details" id="faq-panel-2">
             <p>Most adult cats sleep 12 to 16 hours a day. Kittens and senior cats may sleep even longer because growth and recovery take extra energy.</p>
           </div>
         </div>

         <div class="example" data-component="FAQItem">
           <h3 class="question">
             <button
               class="trigger"
               type="button"
               aria-expanded="true"
               aria-controls="faq-panel-3"
               data-disclosure-button
             >
               <span>Should cats drink milk?</span>
               <span class="icon" aria-hidden="true">+</span>
             </button>
           </h3>
           <div class="details" id="faq-panel-3">
             <p>Many cats are lactose intolerant, so milk can upset their stomachs. Fresh water is the safest daily drink, with treats chosen for cats instead.</p>
           </div>
         </div>

         <div class="example" data-component="FAQItem">
           <h3 class="question">
             <button
               class="trigger"
               type="button"
               aria-expanded="true"
               aria-controls="faq-panel-4"
               data-disclosure-button
             >
               <span>Why do cats knead blankets or people?</span>
               <span class="icon" aria-hidden="true">+</span>
             </button>
           </h3>
           <div class="details" id="faq-panel-4">
             <p>Kneading is a comforting behavior that starts in kittenhood. Adult cats often knead when they feel secure, cozy, or ready to settle down.</p>
           </div>
         </div>

         <div class="example" data-component="FAQItem">
           <h3 class="question">
             <button
               class="trigger"
               type="button"
               aria-expanded="true"
               aria-controls="faq-panel-5"
               data-disclosure-button
             >
               <span>How can I keep an indoor cat entertained?</span>
               <span class="icon" aria-hidden="true">+</span>
             </button>
           </h3>
           <div class="details" id="faq-panel-5">
             <p>Rotate toys, provide scratching posts, offer window views, use puzzle feeders, and schedule short interactive play sessions that let your cat chase and pounce.</p>
           </div>
         </div>
       </section>
     </main>

     <script>
       function DisclosureItem(button) {
         return {
           initialize() {
             const panelId = button.getAttribute("aria-controls");
             const panel = document.getElementById(panelId);

             if (!panel) {
               throw new Error(`Missing disclosure panel: ${panelId}`);
             }

             button.setAttribute("aria-expanded", "false");
             panel.hidden = true;

             button.addEventListener("click", () => {
               const isOpen = button.getAttribute("aria-expanded") === "true";
               button.setAttribute("aria-expanded", String(!isOpen));
               panel.hidden = isOpen;
             });

             button.addEventListener("keydown", (event) => {
               if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
                 button.setAttribute("aria-expanded", "false");
                 panel.hidden = true;
               }
             });
           }
         };
       }

       function initializeDisclosures(root) {
         root.querySelectorAll("[data-disclosure-button]").forEach((button) => {
           DisclosureItem(button).initialize();
         });
       }

       initializeDisclosures(document);
     </script>
   </body>
 </html>

